function execute(inputs) {
  const pv = Number(inputs.pv || 118.2);
  const sp = Number(inputs.sp || 120.0);
  const pb = Number(inputs.pb || 80.0);
  const ti = Number(inputs.ti || 45.0);
  const err = sp - pv;
  const gain = 100.0 / Math.max(pb, 1.0);
